{"results": [{"id": "hp_doc_e1cf52d1539d006818bcf2c6c94dd15a2dd1e27753f59d6e94caa595f07c1068", "title": "Bernard Francis Law", "text": "Bernard Francis Law (born November 4, 1931) is an American cardinal of the Roman Catholic Church. He is Archbishop emeritus of Boston, former archpriest of the Basilica di Santa Maria Maggiore, and Cardinal Priest of Santa Susanna, the American Catholic church in Rome.", "score": 38.5771}, {"id": "hp_doc_232e09e53a56c7d81ad860170ea6e284789defa74f410242a30f5bd01a23fceb", "title": "Letter to U.S. Bishops Concerning Masonry", "text": "The Letter to U.S. Bishops Concerning Masonry was a letter sent on April 19, 1985, by Bernard Francis Cardinal Law, Archbishop of Boston and chairman of the Committee on Pastoral Research and Practices of the United States Catholic Conference. The letter was intended to answer confusion about the admissibility of Masonic membership.", "score": 18.2265}, {"id": "hp_doc_43c9f6395fba03926d843505632e41b829d441d09a216cc63a1f37b4d0c90adb", "title": "Alessandro Verde", "text": "Alessandro Verde (27 March 1865 – 29 March 1958) was an Italian Roman Catholic Cardinal and former Archpriest of the Basilica di Santa Maria Maggiore.", "score": 14.2698}], "remaining_searches": 1}
